import{_ as o,o as a,c as n,a5 as p}from"./chunks/framework.Cooo9kuv.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"837-批量删除txt中每行中指定部分内容V1.0","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["TXT文件批处理"],"标签":["TXT文件批量处理工具","原地修改TXT内容","文本内容删除软件","自定义分隔符处理","递归处理TXT文件"]},"headers":[],"relativePath":"md/TXT文件批处理/837-批量删除txt中每行中指定部分内容V1.0.md","filePath":"md/TXT文件批处理/837-批量删除txt中每行中指定部分内容V1.0.md"}'),r={name:"md/TXT文件批处理/837-批量删除txt中每行中指定部分内容V1.0.md"};function s(e,t,T,g,_,l){return a(),n("div",null,[...t[0]||(t[0]=[p('<p>TXT 文件批量处理工具，按照自定义规则删除 每个TXT 文件中每行中指定分隔符的第 n 个及之前的所有内容，支持处理子文件夹内的 TXT 文件，支持原地修改或保存到指定文件夹（保留目录结构），操作简单且实时显示处理日志，适合批量整理 TXT 文本内容。</p><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p><strong>场景 1：批量清理 TXT 文件每行的前缀编号（空格分隔）</strong></p><p>**场景描述：**电脑中有 “文本资料” 根文件夹，内含多个子文件夹，</p><p>每个文件夹下的 TXT 文件每行内容以 “序号 内容” 格式呈现（<strong>如 “1 今天天气很好”“2 出门散步”</strong>），</p><p>需要删除每行的序号（第 1 个空格前的所有内容），仅保留文本内容，要求原地修改文件。</p><p>**操作步骤：**双击启动工具后，点击 “选择文件夹” 选择 “文本资料” 根文件夹，勾选 “穿透子文件夹”；</p><p>分隔符输入框保持默认空格，删除位置输入框保持默认 1，点击 “添加规则”；</p><p>保存模式选择 “直接在原文档操作”，点击 “开始处理”；等待日志提示 “处理完成” 后，停止操作。</p><p>**预期结果：**所有 TXT 文件每行的序号被删除，<strong>仅保留文本内容（如 “今天天气很好”  “出门散步”）</strong>，文件仍保存在原文件夹中，日志清晰标注成功处理的文件数量，无失败或跳过的文件。</p><p><strong>场景 2：多规则叠加处理 TXT 文件（逗号分隔），保存到指定文件夹</strong></p><p>**场景描述：**有一个 “通讯录” 文件夹，内含多个 TXT 文件，每行内容为 “姓名，年龄，地址，电话” 格式，</p><p><strong>需要先删除姓名（第 1 个逗号前），再删除年龄（第 2 个逗号前），最终仅保留地址和电话，</strong></p><p>要求将处理后的文件保存到 “整理后通讯录” 文件夹并保留原目录结构。</p><p>**操作步骤：**启动工具后，点击 “选择文件夹” 选择 “通讯录” 文件夹，不勾选 “穿透子文件夹”；</p><p>首先在分隔符输入框填写 “,”，删除位置输入框填写 2，<strong>点击 “添加规则”；</strong></p><p>保存模式选择 “保存到指定文件夹（保留结构）”，点击输出路径的 “选择文件夹” 按钮，选择 “整理后通讯录” 文件夹；</p><p>点击 “开始处理” 按钮，等待日志提示处理完成。</p><p>**预期结果：**所有 TXT 文件每行仅保留地址和电话（如 “北京市朝阳区，13800138000”），处理后的文件保存在 “整理后通讯录” 文件夹中且保留原目录结构，原文件未被修改，日志标注所有文件处理成功。</p><h3 id="📑-程序截图" tabindex="-1">📑 程序截图 <a class="header-anchor" href="#📑-程序截图" aria-label="Permalink to &quot;📑 程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251127181316176423839666338.png" alt=""></p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="📑-程序使用说明" tabindex="-1">📑 程序使用说明 <a class="header-anchor" href="#📑-程序使用说明" aria-label="Permalink to &quot;📑 程序使用说明&quot;">​</a></h3><p><strong>双击使用即可，可执行文件（.exe文件），双击该文件即可启动工具</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251127182521176423912155771.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2159.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2159.html</a></p>',31)])])}const c=o(r,[["render",s]]);export{h as __pageData,c as default};
